private Object getEmptyValue(Class<?> attributeType) {
    if (attributeType == null) {
        return null;
    }
    if (attributeType.isPrimitive()) {
        return null;
    }
    if (attributeType.equals(String.class)) {
        return "";
    }
    if (attributeType.equals(Integer.class) || attributeType.equals(Long.class)) {
        return 0L;
    }
    if (attributeType.equals(Double.class) || attributeType.equals(Float.class)) {
