private byte[] getImage(String host, byte[] defaultBytes) {
    try {
        final URL url = new URL("http://" + host + "/image.jpg");
        final HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("GET");
